def themes(text, d):
    t=(text or '').lower().replace('ё','е')
    return [k for k,rx in d.items() if re.search(rx,t)]
def author(text):
    t=(text or '').lower().replace('ё','е')
    for k,rx in AUTHOR.items():
        if re.search(rx,t): return k
    return 'клиент' if len(t)>15 else 'неясно'
